components.custom:
(function() {
    try {
        // دریافت نمونه فرم با اولویت instance.root (استاندارد Form.io در Camunda)
        const form = instance.root || (document.querySelector('.formio') ? document.querySelector('.formio').formio : null);
        if (!form) {
            console.error('Form instance not found');
            return;
        }

        // 1. غیرفعال کردن و مخفی کردن هشدارهای پیش‌فرض بالای صفحه
        form.options = form.options || {};
        form.options.disableAlerts = true; form.options.noAlerts = true;
        const alertBox = document.querySelector('.formio-alerts');
        if (alertBox) alertBox.style.display = 'none';

        const submitBtn = (instance.refs && instance.refs.button) || document.querySelector('button[name="data[' + instance.key + ']"]') || document.querySelector('button[data-key="submit"]');
        const originalText = submitBtn ? submitBtn.innerHTML : 'ثبت و ادامه فرآیند';

        // 2. اعتبارسنجی فرم
        const isValid = form.checkValidity(form.data, true);
        const errors = form.errors || [];

        if (!isValid) {
            // نمایش پاپ‌آپ با تم هماهنگ فرم
            showThemedPopup(errors.length > 0 ? errors : [{ message: 'لطفاً فیلدهای اجباری (علامت‌دار با *) را به درستی پر کنید.' }]);

            // بازگرداندن دکمه به حالت اول
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.style.opacity = '1';
                submitBtn.innerHTML = originalText;
            }
            return; // توقف فرآیند ثبت
        }

        // 3. اگر فرم معتبر بود، ارسال آن
        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.style.opacity = '0.6';
            submitBtn.innerHTML = '⏳ در حال پردازش...';
        }

        form.submit().then(function(submission) { try { var root = form.element || document; Array.prototype.forEach.call(root.querySelectorAll('.alert-success, [ref="buttonMessageContainer"]'), function (el) { el.style.display = 'none'; }); } catch (e0) {}
            // عملیات موفقیت‌آمیز (فرم به طور خودکار توسط Camunda مدیریت می‌شود)
        }).catch(function(err) {
            console.error('Submit error:', err);
            if (submitBtn) {
                submitBtn.disabled = false;
                submitBtn.style.opacity = '1';
                submitBtn.innerHTML = originalText;
            }
            showThemedPopup([{ message: 'خطا در ارتباط با سرور. لطفاً اتصال شبکه را بررسی و مجدداً تلاش کنید.' }]);
        });

        // ============================================================
        // تابع نمایش پاپ‌آپ با تم هماهنگ فرم (نارنجی و خاکستری)
        // ============================================================
        function showThemedPopup(errorList) {
            if (!errorList || errorList.length === 0) return;

            const existingModal = document.getElementById('formErrorModal');
            if (existingModal) existingModal.remove();

            const modal = document.createElement('div');
            modal.id = 'formErrorModal';
            modal.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); display: flex; justify-content: center; align-items: center; z-index: 99999; direction: rtl; font-family: Tahoma, "Segoe UI", "IRANSans", sans-serif; backdrop-filter: blur(2px);';

            const modalContent = document.createElement('div');
            modalContent.style.cssText = 'background: #ffffff; border-radius: 12px; width: 90%; max-width: 500px; max-height: 80vh; box-shadow: 0 10px 40px rgba(0,0,0,0.2); animation: modalSlide 0.3s ease-out; overflow: hidden; display: flex; flex-direction: column;';

            const style = document.createElement('style');
            style.textContent = '@keyframes modalSlide { from { transform: translateY(-30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }';
            document.head.appendChild(style);

            // هدر با رنگ برند فرم (#d35400)
            const modalHeader = document.createElement('div');
            modalHeader.style.cssText = 'background: #d35400; color: white; padding: 16px 20px; display: flex; align-items: center; gap: 12px;';
            modalHeader.innerHTML = '<span style="font-size: 24px;">⚠️</span><div><h3 style="margin: 0; font-size: 16px; font-weight: bold;">بررسی اطلاعات</h3><p style="margin: 4px 0 0; font-size: 12px; opacity: 0.9;">لطفاً موارد زیر را اصلاح کنید</p></div>';

            const modalBody = document.createElement('div');
            modalBody.style.cssText = 'padding: 20px; overflow-y: auto; background: #fafafa; flex: 1;';

            const errorListContainer = document.createElement('div');
            errorList.forEach(function(error) {
                const fieldName = error.component ? (error.component.label || error.component.key || 'یک فیلد') : (error.field || 'یک فیلد');
                const errorMessage = error.message || 'مقدار وارد شده معتبر نیست';

                const errorItem = document.createElement('div');
                // تم هماهنگ با خطاهای فرم‌آی‌او (قرمز ملایم)
                errorItem.style.cssText = 'padding: 12px 15px; margin-bottom: 10px; background: #fdf2f2; border-right: 4px solid #e74c3c; border-radius: 8px; color: #c0392b; font-size: 13px; line-height: 1.6;';
                errorItem.innerHTML = '<strong style="display: block; margin-bottom: 4px; color: #a93226;">' + escapeHtml(fieldName) + ':</strong> ' + escapeHtml(errorMessage);

                errorListContainer.appendChild(errorItem);
            });

            modalBody.appendChild(errorListContainer);

            const modalFooter = document.createElement('div');
            modalFooter.style.cssText = 'padding: 15px 20px; background: #ffffff; border-top: 1px solid #e9ecef; display: flex; justify-content: flex-end;';

            const closeBtn = document.createElement('button');
            closeBtn.textContent = 'متوجه شدم';
            closeBtn.style.cssText = 'background: #d35400; color: white; border: none; padding: 10px 24px; border-radius: 6px; font-size: 13px; font-weight: bold; cursor: pointer; transition: background 0.2s;';
            closeBtn.onmouseover = function() { this.style.background = '#e67e22'; };
            closeBtn.onmouseout = function() { this.style.background = '#d35400'; };
            closeBtn.onclick = function() { modal.remove(); };

            modalFooter.appendChild(closeBtn);
            modalContent.appendChild(modalHeader);
            modalContent.appendChild(modalBody);
            modalContent.appendChild(modalFooter);
            modal.appendChild(modalContent);

            modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
            document.body.appendChild(modal);

            // فوکوس روی دکمه بستن برای دسترسی‌پذیری بهتر
            setTimeout(() => closeBtn.focus(), 100);
        }

        function escapeHtml(str) {
            if (!str) return '';
            return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
        }

    } catch (err) {
        console.error('Submit button error:', err);
        alert('خطایی در فرآیند ثبت رخ داده است: ' + err.message);
    }
})();
